package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.korean.KoreanWordExtractor.ExtractedEntry
import com.danawa.util.CharVector

import org.apache.logging.log4j.LogManager
import org.apache.lucene.analysis.Tokenizer
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.apache.lucene.util.AttributeFactory

import java.io.IOException
import java.util.regex.Pattern

class ProductNameTokenizer : Tokenizer {

    private val termAtt = addAttribute(CharTermAttribute::class.java)
    private val tokenAtt = addAttribute(TokenInfoAttribute::class.java)
    private val offsetAtt = addAttribute(OffsetAttribute::class.java)
    private val typeAtt = addAttribute(TypeAttribute::class.java)

    private var baseOffset = 0
    private var position = 0
    private var extLength = 0
    private var readLength = 0
    private var tokenLength = 0
    private var finalOffset = 0

    private var buffer: CharArray? = null
    private var backBuffer = arrayOf(CharArray(IO_BUFFER_SIZE), CharArray(IO_BUFFER_SIZE))
    private var entry: ExtractedEntry? = null
    private var extractor: KoreanWordExtractor? = null
    private var chrCurrent: Char = 0.toChar()
    private var typeCurrent: String? = null
    private var exportTerm: Boolean = false
    private var tabularFull: Boolean = false

    constructor(dictionary: ProductNameDictionary?, exportTerm: Boolean) {
        if (dictionary != null) {
            extractor = KoreanWordExtractor(dictionary)
            tokenAtt.dictionary(dictionary)
        }
        this.exportTerm = exportTerm
    }

    constructor(factory: AttributeFactory) : super(factory)

    protected fun isTokenChar(c1: Int, c2: Int): Boolean {
        return !Character.isWhitespace(c1)
    }

    @Throws(IOException::class)
    override fun incrementToken(): Boolean {
        typeAtt.setType(null)
        logger.trace("INCREMENT-TOKEN")
        var length = 0
        var start = -1
        var end = -1
        var bufferStart = position
        var continueTerm = false
        var startOffset = 0
        var endOffset = 0
        while (!tokenAtt.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
            if (entry == null) {
                while (true) {
                    if (position >= readLength) {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 1. 원본 읽어오기 (버퍼 크기만큼 읽어옴)
                        ////////////////////////////////////////////////////////////////////////////////
                        val oldBuffer = backBuffer[0]
                        val newBuffer = backBuffer[1]
                        backBuffer[0] = newBuffer
                        backBuffer[1] = oldBuffer
                        baseOffset += readLength
                        readLength = input.read(newBuffer, 0, newBuffer.size)
                        logger.trace("READ {}/{}", newBuffer.size, readLength)
                        if (readLength > 0) {
                            buffer = newBuffer
                            tokenAtt.ref(newBuffer, 0, 0)
                            tokenAtt.rmState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                            entry = null
                            tokenLength = readLength
                            while (tokenLength > 0) {
                                if (getType(newBuffer[tokenLength - 1].code) !== WHITESPACE) {
                                    break
                                }
                                tokenLength--
                            }
                        } else {
                            readLength = 0
                            logger.trace("LENGTH:{} / {}", length, readLength)
                            if (length > 0) {
                                break
                            } else {
                                finalOffset = correctOffset(baseOffset)
                                logger.trace("TOKENIZER STOPPED!!")
                                tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_FINISHED)
                                return false
                            }
                        }
                        if (tokenLength > 0 && tokenLength < FULL_TERM_LENGTH && baseOffset == 0) {
                            // FULL-TERM
                            tokenAtt.ref(newBuffer, 0, tokenLength)
                            tokenAtt.posTag(null)
                            offsetAtt.setOffset(0, tokenLength)
                            typeAtt.setType(FULL_STRING)
                            return true
                        }
                        position = 0
                        bufferStart = 0
                        chrCurrent = 0.toChar()
                        typeCurrent = null
                    }
                    run {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 2. 버퍼 내 단순 토크닝
                        ////////////////////////////////////////////////////////////////////////////////
                        val chrPrev = chrCurrent
                        val typePrev = typeCurrent
                        chrCurrent = buffer!![position]
                        typeCurrent = getType(chrCurrent.code)
                        position++
                        var pass = 1

                        if (typePrev == null) {
                            // nop
                        } else if (typePrev == WHITESPACE && typeCurrent != WHITESPACE) {
                            // nop
                        } else if (typePrev == WHITESPACE && typeCurrent == WHITESPACE) {
                            pass = 2
                        } else if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                            pass = 0
                        } else if (typePrev !== typeCurrent) {
                            pass = 0
                        }

                        if (pass == 1) {
                            if (length == 0) {
                                assert(start == -1)
                                start = baseOffset + position - 1
                                end = start
                            }
                            end++
                            length++
                            if (position >= tokenLength) {
                                break
                            }
                        } else if (pass == 2) {
                            bufferStart = position
                            return@run
                        } else if (length > 0) {
                            if (position >= tokenLength) {
                                position++
                            }
                            if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                                position--
                            } else if (typePrev != WHITESPACE && typeCurrent != WHITESPACE) {
                                position--
                            }
                            length = position - bufferStart
                            break
                        }
                    }
                }

                assert(start != -1)
                startOffset = correctOffset(start)
                endOffset = correctOffset(end)

                if (extractor != null) {
                    logger.trace("TOKEN:{} / {}~{} / {}", CharVector(buffer, bufferStart, length), position - bufferStart, length)
                    extLength = length
                    if (extLength > extractor!!.tabularSize) {
                        extLength = extractor!!.tabularSize
                        tabularFull = true
                    } else {
                        tabularFull = false
                    }
                    logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer, bufferStart, extLength), bufferStart, extLength, baseOffset)
                    extractor!!.setInput(buffer!!, bufferStart, extLength)
                    entry = extractor!!.extract()
                    continue
                } else {
                    tokenAtt.ref(buffer, bufferStart, length)
                    offsetAtt.setOffset(startOffset, endOffset.also { finalOffset = it })
                    logger.trace("TOKEN:{} / {}~{}", tokenAtt.ref(), startOffset, endOffset)
                }
            } else {
                while (entry != null) {
                    ////////////////////////////////////////////////////////////////////////////////
                    // 3. 한글분해
                    ////////////////////////////////////////////////////////////////////////////////
                    if (entry!!.column() <= 0) {
                        entry = entry!!.next()
                        continue
                    }
                    startOffset = correctOffset(baseOffset + entry!!.offset())
                    endOffset = correctOffset(baseOffset + entry!!.offset() + entry!!.column())
                    tokenAtt.ref(buffer, entry!!.offset(), entry!!.column())
                    tokenAtt.posTag(entry!!.posTag())
                    offsetAtt.setOffset(startOffset, endOffset)
                    logger.trace("TERM:{} / {}~{} / {} / {} / {}", tokenAtt.ref(), startOffset, endOffset, baseOffset, readLength, tokenAtt.posTag())
                    if (exportTerm) {
                        if (logger.isTraceEnabled) {
                            logger.trace("{} / {}~{}", String(buffer!!, entry!!.offset(), entry!!.column()), entry!!.offset(), entry!!.column())
                        }
                        termAtt.copyBuffer(buffer, entry!!.offset(), entry!!.column())
                    }
                    val extPosition0 = entry!!.offset() + entry!!.column()
                    var extPosition = extPosition0
                    val prevOffset = entry!!.offset()
                    entry = entry!!.next()
                    while (entry != null) {
                        if (entry!!.offset() < prevOffset) {
                            entry = entry!!.next()
                        } else {
                            break
                        }
                    }

                    if (entry == null) {
                        if (extPosition < position) {
                            if (tabularFull) {
                                logger.trace("CONTINUE-TERM:{}", tokenAtt.ref())
                                if (tokenAtt.ref().length() != extractor!!.tabularSize) {
                                    extPosition -= tokenAtt.ref().length()
                                    continueTerm = true
                                }
                            }
                            extLength = position - extPosition
                            if (extLength > extractor!!.tabularSize) {
                                extLength = extractor!!.tabularSize
                                tabularFull = true
                            } else {
                                tabularFull = false
                            }
                            logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer, extPosition, extLength), extPosition, extLength, baseOffset)
                            extractor!!.setInput(buffer!!, extPosition, extLength)
                            entry = extractor!!.extract()
                            if (continueTerm) {
                                continue
                            }
                        }
                    }
                    var ep = extPosition0
                    while (ep < tokenLength) {
                        if (getType(buffer!![ep].code) !== WHITESPACE) { break }
                        ep++
                    }
                    if (ep == tokenLength) {
                        logger.trace("TOKENIZER BUFFER EXHAUSTED!")
                        tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                        continue
                    }
                    break
                }
                logger.trace("OFFSET:{} / {} / {} / {}", startOffset, endOffset, position, baseOffset + readLength)
            }
            return true
        }
        return false
    }

    @Throws(IOException::class)
    override fun end() {
        logger.trace("TOKENIZER-END {}", finalOffset)
        super.end()
        offsetAtt.setOffset(finalOffset, finalOffset)
    }

    @Throws(IOException::class)
    override fun reset() {
        logger.trace("TOKENIZER-RESET")
        super.reset()
        position = 0
        extLength = 0
        baseOffset = 0
        readLength = 0
        finalOffset = 0
        tokenLength = 0
        chrCurrent = 0.toChar()
        typeCurrent = null
        tabularFull = false
    }

    @Throws(IOException::class)
    override fun close() {
        logger.trace("TOKENIZER-CLOSE")
        super.close()
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(ProductNameTokenizer::class.java)

        @JvmField val DEFAULT_MAX_WORD_LEN = 255
        @JvmField val IO_BUFFER_SIZE = 1000
        @JvmField val FULL_TERM_LENGTH = 64

        @JvmField val WHITESPACE = "<WHITESPACE>"
        @JvmField val SYMBOL = "<SYMBOL>"
        @JvmField val ALPHA = "<ALPHA>"
        @JvmField val NUMBER = "<NUMBER>"
        @JvmField val HANGUL = "<HANGUL>"
        @JvmField val HANGUL_JAMO = "<HANGUL_JAMO>"
        @JvmField val JAPANESE = "<JAPANESE>"
        @JvmField val CHINESE = "<CHINESE>"
        @JvmField val OTHER_LANGUAGE = "<OTHER_LANGUAGE>"
        @JvmField val UNCATEGORIZED = "<UNCATEGORIZED>"

        @JvmField val NUMBER_TRANS = "<NUMBER_TRANS>"
        @JvmField val MODEL_NAME = "<MODEL_NAME>"
        @JvmField val ALPHANUM = "<ALPHANUM>"
        @JvmField val ASCII = "<ASCII>"
        @JvmField val UNIT = "<UNIT>"
        @JvmField val UNIT_ALPHA = "<UNIT_ALPHA>"
        @JvmField val FULL_STRING = "<FULL_STRING>"
        @JvmField val MAKER = "<MAKER>"
        @JvmField val BRAND = "<BRAND>"
        @JvmField val COMPOUND = "<COMPOUND>"
        @JvmField val STOPWORD = "<STOPWORD>"

        @JvmField val MAX_UNIT_LENGTH = 10

        @JvmField val AVAIL_SYMBOLS = charArrayOf('-', '.', '/', '+', '&')
        @JvmField val AVAIL_SYMBOLS_STANDALONE = charArrayOf()
        @JvmField val AVAIL_SYMBOLS_CONNECTOR = charArrayOf('-', '.', '/', '&')

        @JvmField val SYMBOL_COLON = ':'

        @JvmField val PTN_NUMBER: Pattern = Pattern.compile(
            "^(" +
                "(" +
                    "(" +
                        "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                        "([0-9]+)" +
                    ")" +
                    "([.][0-9]+)*" +
                ")" +
            ")" +
            "(" +
                "[:]" +
                "(" +
                    "(" +
                        "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                        "([0-9]+)" +
                    ")" +
                    "([.][0-9]+)*" +
                ")" +
            "){0,1}" +
            "$"
        )

        @JvmField val AVAIL_SYMBOLS_INNUMBER = charArrayOf(',', '.', SYMBOL_COLON)
        @JvmField val AVAIL_SYMBOLS_SPLIT = charArrayOf(',', '|', '[', ']', '<', '>', '{', '}', '^')

        @JvmStatic
        fun containsChar(array: CharArray, c: Char): Boolean {
            for (ch in array) {
                if (ch == c) {
                    return true
                }
            }
            return false
        }

        @JvmStatic
        fun containsChar(array: CharArray, buf: CharArray, length: Int): Boolean {
            for (ch in array) {
                if (!containsChar(array, ch)) {
                    return false
                }
            }
            return true
        }

        @JvmStatic
        fun isSplit(c: Char): String? {
            val ret = getType(c.code)
            if (ret == WHITESPACE || ret == SYMBOL) {
                return ret
            } else if (ret == SYMBOL && (containsChar(AVAIL_SYMBOLS_SPLIT, c) || (c.code > 128))) {
                return ret
            }
            return null
        }

        @JvmStatic
        fun getUniType(cv: CharSequence): String? {
            var ret: String? = null
            var prevType: String? = null
            var type: String? = null
            for (inx in 0 until cv.length) {
                prevType = type
                type = getType(cv[inx].code)
                if (prevType != null && type != prevType) {
                    if (prevType != type) {
                        type = UNCATEGORIZED
                        break
                    }
                }
            }
            ret = type
            return ret
        }

        @JvmStatic
        fun isAlphaNum(cv: CharVector): Boolean {
            var ret = true
            if (cv.length() == 0) {
                return false
            }
            for (inx in 0 until cv.length()) {
                val type = getType(cv.array()[cv.offset() + inx].code)
                if (!(type == ALPHA || type == NUMBER)) {
                    ret = false
                    break
                }
            }
            return ret
        }

        @JvmStatic
        fun getTermType(cv: CharSequence): String? {
            var ret: String? = null
            var prevType: String? = null
            var type: String? = null
            for (inx in 0 until cv.length) {
                prevType = type
                type = getType(cv[inx].code)
                if (prevType != null && type !== prevType) {
                    type = if ((prevType === ALPHA && type === NUMBER) || (prevType === NUMBER && type === ALPHA)) {
                        ALPHANUM
                    } else if (prevType === ALPHANUM && (type === ALPHA || type === NUMBER)) {
                        ALPHANUM
                    } else if ((prevType === ALPHA && type === SYMBOL) || (prevType === NUMBER && type === SYMBOL)
                        || (prevType === ALPHANUM && type === SYMBOL)) {
                        ASCII
                    } else if (prevType === ASCII && (type === ALPHA || type === NUMBER || type === SYMBOL)) {
                        ASCII
                    } else {
                        UNCATEGORIZED
                    }
                }
            }
            ret = type
            return ret
        }

        @JvmStatic
        fun getType(ch: Int): String {
            if (Character.isWhitespace(ch)) {
                return WHITESPACE
            }

            val type = Character.getType(ch)

            when (type) {
                Character.DASH_PUNCTUATION.toInt(),
                Character.START_PUNCTUATION.toInt(),
                Character.END_PUNCTUATION.toInt(),
                Character.CONNECTOR_PUNCTUATION.toInt(),
                Character.OTHER_PUNCTUATION.toInt(),
                Character.MATH_SYMBOL.toInt(),
                Character.CURRENCY_SYMBOL.toInt(),
                Character.MODIFIER_SYMBOL.toInt(),
                Character.OTHER_SYMBOL.toInt(),
                Character.INITIAL_QUOTE_PUNCTUATION.toInt(),
                Character.FINAL_QUOTE_PUNCTUATION.toInt() -> return SYMBOL

                Character.OTHER_LETTER.toInt() -> {
                    val unicodeBlock = Character.UnicodeBlock.of(ch)
                    return when (unicodeBlock) {
                        Character.UnicodeBlock.HANGUL_SYLLABLES -> HANGUL
                        Character.UnicodeBlock.HANGUL_COMPATIBILITY_JAMO -> HANGUL_JAMO
                        Character.UnicodeBlock.HIRAGANA, Character.UnicodeBlock.KATAKANA -> JAPANESE
                        Character.UnicodeBlock.CJK_UNIFIED_IDEOGRAPHS -> CHINESE
                        else -> OTHER_LANGUAGE
                    }
                }

                Character.UPPERCASE_LETTER.toInt(),
                Character.LOWERCASE_LETTER.toInt() -> return ALPHA

                Character.DECIMAL_DIGIT_NUMBER.toInt() -> return NUMBER
            }

            return UNCATEGORIZED
        }
    }
}

package com.danawa.search.analysis.product.rule

import com.danawa.search.analysis.dict.SetDictionary
import com.danawa.search.analysis.dict.SynonymDictionary
import com.danawa.search.analysis.product.AnalyzerOption
import com.danawa.search.analysis.product.ProductNameTokenizer.*
import com.danawa.util.CharVector

class RuleThree(
    entry: Entry, fullExtract: Boolean, option: AnalyzerOption,
    unitDictionary: SetDictionary?,
    unitSynonymDictionary: SynonymDictionary?
) : Rule(entry, fullExtract, option) {

    init {
        this.unitDictionary = unitDictionary
        this.unitSynonymDictionary = unitSynonymDictionary
    }

    override fun apply(queue: MutableList<RuleEntry>) {
        var nextNextEntry: RuleEntry? = null

        var qinx = 0
        while (qinx < queue.size) {
            val currentEntry = queue[qinx]
            if (isFullStringEntry(currentEntry)) {
                qinx++
                continue
            }

            if (existNextIndex(queue, qinx)) {
                val nextEntry = queue[qinx + 1]
                if (isConnectedNumberEntry(currentEntry, nextEntry)) {
                    nextNextEntry = getUnit(queue, nextNextEntry, qinx, currentEntry, nextEntry)
                }
            }
            qinx++
        }

        logger.trace("3rd process complete / queue:{}", queue)
    }

    private fun getUnit(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry): RuleEntry? {
        var result = nextNextEntry
        val unitCandidate = CharVector()
        unitCandidate.init(nextEntry.buf, nextEntry.start, nextEntry.length)

        var findInx = 5
        var foundUnit = false
        while (findInx > 0) {
            if (qinx + findInx < queue.size) {
                val prevEntry = queue[qinx + findInx]
                if (prevEntry.length == 0 || (findInx > 1 && isHangulEntry(prevEntry))) {
                    findInx--
                    continue
                }
                val unitLength = getUnitLength(nextEntry, prevEntry)
                if (unitLength <= MAX_UNIT_LENGTH) {
                    if (nextEntry.buf.size >= nextEntry.start + unitLength) {
                        unitCandidate.init(nextEntry.buf, nextEntry.start, unitLength)
                        if (findUnitDictionary(unitCandidate, getUniType(unitCandidate))) {
                            foundUnit = true
                            break
                        }
                    }
                }
            }
            findInx--
        }

        if (foundUnit) {
            result = getRuleEntry(queue, result, qinx, currentEntry, nextEntry, unitCandidate, findInx)
        }
        return result
    }

    private fun getUnitLength(nextEntry: RuleEntry, prevEntry: RuleEntry): Int {
        return if (isSameBuffer(nextEntry, prevEntry)) {
            prevEntry.start + prevEntry.length - nextEntry.start
        } else {
            nextEntry.length
        }
    }

    private fun isSameBuffer(nextEntry: RuleEntry, prevEntry: RuleEntry): Boolean {
        return prevEntry.buf == nextEntry.buf
    }

    private fun isConnectedNumberEntry(currentEntry: RuleEntry, nextEntry: RuleEntry): Boolean {
        return isConnected(currentEntry, nextEntry) && (isNumberEntry(currentEntry) || isNumberTransEntry(currentEntry))
    }

    private fun getRuleEntry(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int): RuleEntry? {
        var result = nextNextEntry
        val unitType = getUniType(unitCandidate)
        var units: Array<CharSequence>? = null
        if (unitSynonymDictionary != null) {
            units = unitSynonymDictionary!!.get(unitCandidate)
        }
        var tempch1: Char = 0x0.toChar()
        if (currentEntry.start > entry.start) {
            tempch1 = currentEntry.buf[currentEntry.start - 1]
        }

        val typePrev = setTypePrev(queue, qinx)

        if (isAllMatchTerm(queue, qinx, nextEntry, unitCandidate, findInx)) {
            if (isAlphaWithUnit(typePrev, unitType, tempch1)) {
                processUnitSynonym(queue, qinx, currentEntry, nextEntry, unitCandidate, findInx, unitType, units)
            }
        } else if (isReduceTerm(nextEntry, unitCandidate)) {
            result = getXNextEntry(queue, result, qinx)
            currentEntry.modifiable = true
            nextEntry.modifiable = true
        }
        return result
    }

    private fun setTypePrev(queue: MutableList<RuleEntry>, qinx: Int): String? {
        return if (qinx > 0) {
            queue[qinx - 1].type
        } else {
            null
        }
    }

    private fun getXNextEntry(queue: MutableList<RuleEntry>, nextNextEntry: RuleEntry?, qinx: Int): RuleEntry? {
        return if (qinx + 2 < queue.size) {
            queue[qinx + 2]
        } else {
            nextNextEntry
        }
    }

    private fun processUnitSynonym(queue: MutableList<RuleEntry>, qinx: Int, currentEntry: RuleEntry, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int, unitType: String?, units: Array<CharSequence>?) {
        Entry.modifyRuleEntry(fullExtract, option, currentEntry, nextEntry, unitCandidate, units, unitType)
        logger.trace("currentEntry:{} / SYN:{}", currentEntry, currentEntry.synonym)
        var isNumberTransEntry = false
        for (e in currentEntry.subEntry) {
            if (e.type == NUMBER_TRANS) {
                isNumberTransEntry = true
                break
            }
        }
        var fi = findInx
        while (fi >= 1) {
            if (!isNumberTransEntry && (currentEntry.type != UNIT)) {
                queue.removeAt(qinx + fi)
            } else if (option.useForQuery()) {
                queue.removeAt(qinx + fi)
            }
            fi--
        }
    }

    private fun isAlphaWithUnit(typePrev: String?, unitType: String?, tempch1: Char): Boolean {
        return (unitType == ALPHA && (typePrev == UNIT || typePrev == UNIT_ALPHA)) ||
                !(getType(tempch1) == ALPHA && unitType == ALPHA)
    }

    private fun isReduceTerm(nextEntry: RuleEntry, unitCandidate: CharVector): Boolean {
        return nextEntry.buf.size > nextEntry.start + unitCandidate.length()
    }

    private fun isAllMatchTerm(queue: MutableList<RuleEntry>, qinx: Int, nextEntry: RuleEntry, unitCandidate: CharVector, findInx: Int): Boolean {
        return (findInx == 1 && unitCandidate.length() == nextEntry.length) ||
                (findInx > 1 && (qinx + findInx) < queue.size && unitCandidate.length() ==
                        queue[qinx + findInx].endOffset - nextEntry.startOffset)
    }

    private fun findUnitDictionary(key: CharVector, type: String?): Boolean {
        key.ignoreCase()
        if (isEquals(type, ALPHA) || isEquals(type, SYMBOL)) {
            if (key.length() > MAX_UNIT_LENGTH) {
                key.length(MAX_UNIT_LENGTH)
            }
            if (checkUnitDictionary(key)) return true
            key.length(key.length() - 1)
            return false
        } else {
            return isContainUnitDictionary(key)
        }
    }

    private fun checkUnitDictionary(key: CharVector): Boolean {
        var len = key.length()
        while (len >= 0) {
            key.length(len)
            if (isContainUnitDictionary(key)) return true
            len--
        }
        return false
    }

    private fun isContainUnitDictionary(key: CharVector): Boolean {
        return unitDictionary != null && unitDictionary!!.set().contains(key)
    }
}

package com.danawa.search.analysis.product.rule

import com.danawa.search.analysis.dict.CompoundDictionary
import com.danawa.search.analysis.dict.SetDictionary
import com.danawa.search.analysis.dict.SpaceDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.product.AnalyzerOption
import com.danawa.search.analysis.product.ProductNameTokenizer.*
import com.danawa.util.CharVector
import java.util.Collections

class RuleOne(
    entry: Entry, fullExtract: Boolean, option: AnalyzerOption,
    spaceDictionary: SpaceDictionary?,
    stopDictionary: SetDictionary?,
    userDictionary: SetDictionary?,
    unitDictionary: SetDictionary?,
    compoundDictionary: CompoundDictionary?,
    extractor: KoreanWordExtractor?
) : Rule(entry, fullExtract, option) {

    init {
        this.spaceDictionary = spaceDictionary
        this.stopDictionary = stopDictionary
        this.userDictionary = userDictionary
        this.unitDictionary = unitDictionary
        this.compoundDictionary = compoundDictionary
        this.extractor = extractor
    }

    override fun apply(queue: MutableList<RuleEntry>) {
        val cvTmp = CharVector()
        cvTmp.ignoreCase()
        var eTerm: CharVector
        var currentEntry: RuleEntry
        var nextEntry: RuleEntry
        var prevEntry: RuleEntry
        Collections.sort(queue)

        var qinx = 0
        while (qinx < queue.size) {
            currentEntry = queue[qinx]
            if (isFullStringEntry(currentEntry)) {
                qinx++
                continue
            }
            if (currentEntry.length == 0) {
                setDisableEntry(queue, currentEntry, qinx)
                qinx++
                continue
            }

            if (currentEntry.type == UNCATEGORIZED) {
                if (!userDictionary!!.contains(currentEntry.makeTerm(null))) {
                    val entry = queue.removeAt(qinx)
                    Entry.split(entry, queue, qinx)
                    currentEntry = queue[qinx]
                } else {
                    currentEntry.type = HANGUL
                }
            }
            cvTmp.init(currentEntry.buf, currentEntry.start, currentEntry.length)

            if (fullExtract) {
                qinx = ruleFullExtract(queue, cvTmp, currentEntry, qinx)
            }
            currentEntry = queue[qinx]

            if (currentEntry.type == HANGUL && currentEntry.modifiable) {
                if (getType(currentEntry.buf[currentEntry.start]) == NUMBER) {
                    var numInx = 1
                    var numberTrans = false
                    while (numInx < currentEntry.length) {
                        val ch = currentEntry.buf[currentEntry.start + numInx]
                        val numberChar = containsChar(AVAIL_SYMBOLS_INNUMBER, ch)
                        if (numberChar) {
                            numberTrans = true
                        }
                        if (getType(ch) != NUMBER && !numberChar) {
                            break
                        }
                        numInx++
                    }
                    val unitCv = CharVector(currentEntry.buf, currentEntry.start + numInx, currentEntry.length - numInx)
                    if (unitDictionary != null && unitDictionary!!.contains(unitCv)) {
                        qinx = ruleUnitDict(queue, currentEntry, qinx, numInx, numberTrans, unitCv)
                        qinx++
                        continue
                    }
                } else {
                    if (currentEntry.length <= 3 && currentEntry.modifiable) {
                        eTerm = currentEntry.makeTerm(null)
                        var joinable = false
                        if (userDictionary != null && !userDictionary!!.contains(eTerm)) {
                            if (isAlphaNum(eTerm)) {
                                if (qinx > 0) {
                                    prevEntry = queue[qinx - 1]
                                    joinable = currentEntry.start == prevEntry.start + prevEntry.length && (prevEntry.type == ALPHA || prevEntry.type == NUMBER || prevEntry.type == SYMBOL)
                                }
                                if (!joinable && qinx + 1 < queue.size) {
                                    nextEntry = queue[qinx + 1]
                                    joinable = nextEntry.start == currentEntry.start + currentEntry.length && (nextEntry.type == ALPHA || nextEntry.type == NUMBER || nextEntry.type == SYMBOL)
                                }
                                if (joinable) {
                                    queue.removeAt(qinx)
                                    Entry.split(currentEntry, queue, qinx)
                                }
                                qinx++
                                continue
                            }
                        }
                        val eType = getTermType(eTerm)
                        if (eType == ALPHA) {
                            currentEntry.type = ALPHA
                        } else if (eType == NUMBER) {
                            logger.trace("NUMBER FOUND:{}", currentEntry)
                            currentEntry.type = NUMBER
                        } else if (eType == ASCII || eType == ALPHANUM) {
                            currentEntry.type = MODEL_NAME
                        }
                    }
                }
            }
            if (qinx + 1 < queue.size) {
                prevEntry = queue[qinx + 1]
                logger.trace("currentEntry0:{}/prevEntry:{} {}:{}", currentEntry, prevEntry, currentEntry.endOffset, prevEntry.startOffset)
                qinx = ruleNumberEntry(queue, currentEntry, prevEntry, qinx)
            }
            qinx++
        }
        logger.trace("1st process complete / queue:{}", queue)
    }

    private fun ruleFullExtract(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
        var prevEntry: RuleEntry
        var ctype = getType(currentEntry.buf[currentEntry.start + currentEntry.length - 1])
        for (linx in 10 downTo 1) {
            var passFlag = 0
            val tmpBuf = currentEntry.buf
            val tmpSt = currentEntry.start
            var tmpEd: Int

            if (queue.size > qinx + linx) {
                prevEntry = queue[qinx + linx]
                if (prevEntry.buf == tmpBuf && prevEntry.length > 0 && prevEntry.type != FULL_STRING) {
                    tmpEd = prevEntry.start + prevEntry.length
                    val tmpStCh = if (tmpSt > 0) tmpBuf[tmpSt - 1] else 0.toChar()
                    val tmpEdCh = if (tmpEd < entry.lastPosition) tmpBuf[tmpEd] else 0.toChar()
                    val tmpStCType = getType(tmpStCh)
                    val tmpEdCType = getType(tmpEdCh)
                    passFlag = ruleCombineEntry(queue, currentEntry, qinx, ctype, linx, passFlag, tmpSt, tmpEd, tmpStCh, tmpEdCh, tmpStCType, tmpEdCType)
                    ctype = tmpEdCType
                }
            }

            if (passFlag != 0) {
                prevEntry = queue[qinx + linx]
                cvTmp.init(currentEntry.buf, currentEntry.start, prevEntry.start + prevEntry.length - currentEntry.start)
                passFlag = 0

                if (spaceDictionary != null && spaceDictionary!!.containsKey(cvTmp)) {
                    val currentTerm = CharVector()
                    currentTerm.init(currentEntry.buf, currentEntry.start, currentEntry.length)
                    val prevTerm = CharVector()
                    prevTerm.init(prevEntry.buf, prevEntry.start, prevEntry.length)
                    if (!unitDictionary!!.contains(currentTerm) && !unitDictionary!!.contains(prevTerm)) {
                        passFlag = 1
                    }
                } else if (stopDictionary != null && stopDictionary!!.contains(cvTmp)) {
                    passFlag = 2
                } else if (containsDictionary(cvTmp)) {
                    passFlag = 3
                }

                if (passFlag != 0) {
                    Entry.merge(currentEntry, prevEntry, HANGUL)
                    if (qinx + linx >= qinx) {
                        queue.subList(qinx, qinx + linx + 1).clear()
                    }
                    return when (passFlag) {
                        1 -> ruleSpaceDict(queue, cvTmp, currentEntry, qinx)
                        2 -> { ruleStopDict(queue, currentEntry, qinx); qinx }
                        else -> { queue.add(qinx, currentEntry); qinx }
                    }
                }
            }
        }
        return qinx
    }

    private fun ruleUnitDict(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int, numInx: Int, numberTrans: Boolean, unitCv: CharVector): Int {
        val prevEntry = currentEntry.clone()
        currentEntry.length = numInx
        currentEntry.endOffset = currentEntry.startOffset + currentEntry.length
        logger.trace("NUMBER FOUND:{} / {}", currentEntry, prevEntry)
        if (numberTrans) {
            currentEntry.type = NUMBER_TRANS
        } else {
            currentEntry.type = NUMBER
        }
        prevEntry.start += numInx
        prevEntry.length -= numInx
        prevEntry.type = getTermType(unitCv)
        queue.add(qinx + 1, prevEntry)
        return qinx + 1
    }

    private fun ruleCombineEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int, ctype: String?, linx: Int, passFlag: Int, tmpSt: Int, tmpEd: Int, tmpStCh: Char, tmpEdCh: Char, tmpStCType: String?, tmpEdCType: String?): Int {
        var nextEntry: RuleEntry
        var prevEntry: RuleEntry
        if ((tmpSt == 0 || (tmpStCh.code != 0 && (tmpStCh == ' ' || tmpStCType != ctype))) &&
            (tmpEd == entry.lastPosition || (tmpEdCh.code != 0 && (tmpEdCh == ' ' || tmpEdCType != ctype)))) {
            var flag = 1
            prevEntry = currentEntry
            for (tinx in 0 until linx) {
                nextEntry = queue[qinx + tinx + 1]
                if (nextEntry.length == 0 || nextEntry.type == FULL_STRING || nextEntry.start != prevEntry.start + prevEntry.length) {
                    flag = 0
                    break
                }
                prevEntry = nextEntry
            }
            return flag
        }
        return passFlag
    }

    private fun ruleStopDict(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int) {
        currentEntry.modifiable = false
        queue.add(qinx, currentEntry)
    }

    private fun ruleSpaceDict(queue: MutableList<RuleEntry>, cvTmp: CharVector, currentEntry: RuleEntry, qinx: Int): Int {
        var prevEntry: RuleEntry
        val splits = spaceDictionary!!.get(cvTmp)
        var start = currentEntry.start
        var startOffset = currentEntry.startOffset
        for (sinx in splits!!.indices) {
            val split = splits[sinx]
            prevEntry = RuleEntry(currentEntry.buf, start, split.length,
                startOffset, startOffset + split.length, HANGUL)
            ruleStopDict(queue, prevEntry, qinx + sinx)
            start += prevEntry.length
            startOffset += prevEntry.length
        }
        return qinx + splits.size - 1
    }

    private fun ruleNumberEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, prevEntry: RuleEntry, qinx: Int): Int {
        if ((currentEntry.type == NUMBER || currentEntry.type == NUMBER_TRANS)
            && prevEntry.type == NUMBER && currentEntry.endOffset != prevEntry.startOffset) {
            val c = currentEntry.buf[currentEntry.start + currentEntry.length]
            if (logger.isTraceEnabled) {
                logger.trace("c:{} / type:{} / contains:{}", c, getType(c), containsChar(AVAIL_SYMBOLS_INNUMBER, c))
            }
            if (getType(c) == SYMBOL && containsChar(AVAIL_SYMBOLS_INNUMBER, c)) {
                queue.removeAt(qinx + 1)
                currentEntry.length += 1 + prevEntry.length
                currentEntry.endOffset = prevEntry.endOffset
                currentEntry.type = NUMBER_TRANS
                return qinx - 1
            }
        }
        return qinx
    }

    private fun setDisableEntry(queue: MutableList<RuleEntry>, currentEntry: RuleEntry, qinx: Int) {
        currentEntry.modifiable = false
        if (qinx > 0 && qinx + 1 < queue.size) {
            queue[qinx - 1].modifiable = false
            queue[qinx + 1].modifiable = false
        }
    }
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
