    @Throws(Exception::class)
    fun testByInputText(r1: ReflectHelper, r2: ReflectHelper,
                        context: MutableMap<String, Any>, str: String) {
        for (inx in 0 until 2) {
            val list1 = launchDanawasearch(r2, context, str, inx == 0)
            val list2 = launchFastcatsearch(r1, context, str, inx == 0)
            log(DEBUG, "TERMS1:{}", JSON.obj2JSON(list1))
            log(DEBUG, "TERMS2:{}", JSON.obj2JSON(list2))
        }
    }

    @Throws(Exception::class)
    fun testByFile(r1: ReflectHelper, r2: ReflectHelper,
                   context: MutableMap<String, Any>, path: String) {
        val f = File(path)
        if (!f.exists()) { return }
        val reader = FilesReader(f)
        while (reader.isAvail()) {
            var str = reader.readLine() ?: continue
            str = str.trim()
            if (str.isEmpty() || str.startsWith("#")) {
                continue
            }
            testByInputText(r1, r2, context, str)
        }
        reader.close()
    }

    @Suppress("UNCHECKED_CAST")
    @Throws(Exception::class)
    fun initFastcatsearch(rh: ReflectHelper, context: MutableMap<String, Any>, dir: File) {
        val ctxProps = context["ctxProps"] as List<Map<String, Any>>
        val dictSetting = mutableListOf<Any>()

        for (inx in ctxProps.indices) {
            val prop = ctxProps[inx]
            val clsTypes = rh.cls(DictionaryType)
            val item = rh.inst(DictionarySetting)
            val type = rh.runS(clsTypes, "valueOf", ar(prop["type"]))
            rh.batch(item,
                ar("setId", ar(prop["name"])),
                ar("setName", ar(prop["name"])),
                ar("setType", ty(clsTypes), ar(type)),
                ar("setIgnoreCase", ty(Boolean::class.javaPrimitiveType!!), ar("true" == prop["ignoreCase"]))
            )
            dictSetting.add(item!!)
        }
        val clsSettings = rh.cls("PluginSetting")
        val settings = rh.inst("AnalysisPluginSetting")
        rh.batch(settings,
            ar("setId", ar("Product")),
            ar("setNamespace", ar("Analysis")),
            ar("setClassName", ar(ProductAnalysisPlugin)),
            ar("setVersion", ar("1.0")),
            ar("setUseDB", ty(Boolean::class.javaPrimitiveType!!), ar(false)),
            ar("setDictionarySettingList", ty(MutableList::class.java), ar(dictSetting))
        )
        val plugin = rh.inst(ProductAnalysisPlugin,
            ty(File::class.java, clsSettings, String::class.java), ar(dir, settings, ""))
        rh.run(plugin, "load", ty(Boolean::class.javaPrimitiveType!!), ar(false))
        val dict = rh.run(plugin, "getDictionary")
        context[DICT_FASTCATSEARCH] = dict!!
    }

    @Throws(Exception::class)
    fun initDanawasearch(rh: ReflectHelper, context: MutableMap<String, Any>, dir: File) {
        val file = File(dir, "product-name-dictionary.yml")
        val ctxProps = mutableListOf<Map<String, Any>>()
        context["ctxProps"] = ctxProps

        val cfgProps = rh.runS(rh.cls("ResourceResolver"), "readYmlConfig", ar(file))!!
        val itemList = JSON.optArray(cfgProps, "dictionary")
        val length = JSON.size(itemList)
        for (inx in 0 until length) {
            val item = JSON.optMap(itemList, inx)
            val prop = mutableMapOf<String, Any>(
                "name" to (JSON.optStr(item, "name", "") ?: ""),
                "type" to (JSON.optStr(item, "type", "") ?: ""),
                "tokenType" to (JSON.optStr(item, "tokenType", "") ?: ""),
                "ignoreCase" to (JSON.optStr(item, "ignoreCase", "") ?: ""),
                "filePath" to (JSON.optStr(item, "filePath", "") ?: "")
            )
            ctxProps.add(prop)
        }
        val dict = rh.runS(rh.cls("ProductNameDictionary"), "loadDictionary",
            ty(File::class.java, cfgProps.javaClass), ar(file.parentFile, cfgProps))
        context[DICT_DANAWASEARCH] = dict!!
    }

    @Suppress("UNCHECKED_CAST")
    @Throws(Exception::class)
    fun launchDanawasearch(rh: ReflectHelper, context: MutableMap<String, Any>, str: String, useForQuery: Boolean): List<Any> {
        val termList = mutableListOf<Any>()
        val FULL_STRING = rh.field("ProductNameTokenizer", "FULL_STRING")
        val dict = context[DICT_DANAWASEARCH]!!
        val reader: Reader = StringReader(str)
        val option = rh.inst("AnalyzerOption",
            ty(Boolean::class.javaPrimitiveType!!, Boolean::class.javaPrimitiveType!!, Boolean::class.javaPrimitiveType!!, Boolean::class.javaPrimitiveType!!, Boolean::class.javaPrimitiveType!!),
            ar(useForQuery, true, true, true, false))
        rh.run(option, "useSynonym", ty(Boolean::class.javaPrimitiveType!!), ar(true))
        val tokenizer = rh.inst("ProductNameTokenizer", ty(dict.javaClass, Boolean::class.javaPrimitiveType!!), ar(dict, true))
        rh.run(tokenizer, "setReader", ty(Reader::class.java), ar(reader))
        val tstream = rh.inst("ProductNameAnalysisFilter",
            ty(rh.cls("TokenStream"), dict.javaClass, option!!.javaClass),
            ar(tokenizer, dict, option))

        val termAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("CharTermAttribute")))
        val offsAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("OffsetAttribute")))
        val typeAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("TypeAttribute")))
        val synmAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("SynonymAttribute")))
        val extrAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("ExtraTermAttribute")))
        val poscAtr = rh.runA(tstream, "addAttribute", ar(rh.cls("PositionIncrementAttribute")))

        rh.run(tstream, "reset")
        while (java.lang.Boolean.TRUE == rh.run(tstream, "incrementToken")) {
            var type = rh.run(typeAtr, "type")
            val posc = rh.run(poscAtr, "getPositionIncrement")
            var offst = rh.run(offsAtr, "startOffset")
            var offed = rh.run(offsAtr, "endOffset")
            var synm = rh.run(synmAtr, "getSynonyms") as List<*>?
            val extr = rh.run(extrAtr, "iterator") as Iterator<*>?
            if (FULL_STRING == type) { continue }

            var termInfo = mutableMapOf<String, Any>(
                "term" to termAtr.toString(),
                "type" to type.toString()
            )
            val current = mutableListOf<Any>()
            if (!useForQuery) { synm = null }
            log(TRACE, "TERM:{} / {} [{}: {}~{}] / {} / {}", termAtr, type, posc, offst, offed, synm, extr != null)
            if (synm != null) {
                for (inx in synm.indices) {
                    val syn = synm[inx]!!
                    termInfo["syn"] = syn
                    log(TRACE, "SYN:{}", syn)
                }
            }
            current.add(termInfo)
            while (extr != null && extr.hasNext()) {
                val eterm = extr.next()
                type = rh.run(typeAtr, "type")
                offst = rh.run(offsAtr, "startOffset")
                offed = rh.run(offsAtr, "endOffset")
                synm = rh.run(synmAtr, "getSynonyms") as List<*>?
                termInfo = mutableMapOf(
                    "term" to eterm.toString(),
                    "type" to type.toString()
                )
                if (!useForQuery) { synm = null }
                log(TRACE, "EXT:{} / {} [{}: {}~{}] / {}", eterm, type, posc, offst, offed, synm)
                if (synm != null) {
                    for (inx in synm.indices) {
                        val syn = synm[inx]!!
                        termInfo["syn"] = syn
                        log(TRACE, "SYN:{}", syn)
                    }
                }
                current.add(termInfo)
            }
            termList.add(current)
        }
        rh.run(tstream, "close")
        rh.run(tokenizer, "close")
        return termList
    }

    @Suppress("UNCHECKED_CAST")
