            current.add(termInfo)
            while (extr != null && extr.hasNext()) {
                val eterm = extr.next()
                type = rh.run(typeAtr, "type")
                offst = rh.run(offsAtr, "startOffset")
                offed = rh.run(offsAtr, "endOffset")
