    class ReflectHelper(paths: Array<String>) {
        private val loader: ClassLoader
        private val classMap: MutableMap<String, Class<*>>

        fun loader(): ClassLoader = loader

        init {
            val urlList = mutableListOf<URL>()
            val fileFilter = object : FileFilter {
                override fun accept(file: File): Boolean {
                    if (!file.exists()) { return false }
                    if (file.isDirectory) { file.listFiles(this) }
                    val path = file.absolutePath
                    if (path.endsWith(".jar")) {
                        try {
                            urlList.add(URL("jar:file:$path!/"))
                        } catch (ignore: Exception) { }
                    }
                    return false
                }
            }
            for (path in paths) {
                File(path).listFiles(fileFilter)
            }
            val urls = urlList.toTypedArray()
            this.loader = URLClassLoader(urls, Thread.currentThread().contextClassLoader)
            this.classMap = mutableMapOf()
        }

        @Throws(Exception::class)
        fun init(classNames: Array<String>) {
            for (clsName in classNames) {
                cls(clsName)
            }
        }

        @Throws(Exception::class)
        fun cls(clsName: String): Class<*> {
            var cls: Class<*>? = null
            try {
                cls = classMap[clsName]
            } catch (ignore: Exception) { }
            if (cls == null) {
                cls = loader.loadClass(clsName)
                classMap[cls.simpleName] = cls
                classMap[cls.name] = cls
            }
            return cls
        }

        @Throws(Exception::class)
        fun inst(clsName: String): Any? {
            return inst(clsName, null, null)
        }

        @Throws(Exception::class)
        fun inst(clsName: String, types: Array<Class<*>>?, args: Array<Any?>?): Any? {
            val cls = cls(clsName)
            return inst(cls, types, args)
        }

        @Throws(Exception::class)
        fun inst(cls: Class<*>): Any? {
            return inst(cls, null, null)
        }

        @Throws(Exception::class)
        fun inst(cls: Class<*>, types: Array<Class<*>>?, args: Array<Any?>?): Any? {
            val t = types ?: emptyArray()
            val a = args ?: emptyArray()
            val constructor = cls.getConstructor(*t)
            return constructor.newInstance(*a)
        }

        @Throws(Exception::class)
        fun method(cls: Class<*>, name: String, types: Array<Class<*>>?): Method {
            val t = types ?: emptyArray()
            return cls.getMethod(name, *t)
        }

        @Throws(Exception::class)
        fun runS(clsName: String, name: String, types: Array<Class<*>>?, args: Array<Any?>?): Any? {
            return runS(cls(clsName), name, types, args)
        }

        @Throws(Exception::class)
        fun runS(cls: Class<*>, name: String): Any? {
            return runS(cls, name, null, null)
        }

        @Throws(Exception::class)
        fun runS(cls: Class<*>, name: String, types: Array<Class<*>>?, args: Array<Any?>?): Any? {
            val t = types ?: emptyArray()
            val a = args ?: emptyArray()
            val method = cls.getMethod(name, *t)
            return method.invoke(null, *a)
        }

        @Throws(Exception::class)
        fun run(inst: Any?, name: String): Any? {
            return run(inst, name, null, null)
        }

        @Throws(Exception::class)
        fun run(inst: Any?, name: String, types: Array<Class<*>>?, args: Array<Any?>?): Any? {
            val t = types ?: emptyArray()
            val a = args ?: emptyArray()
            val cls = inst!!.javaClass
            val method = cls.getMethod(name, *t)
            return method.invoke(inst, *a)
        }

        @Throws(Exception::class)
        fun runS(cls: Class<*>, name: String, args: Array<Any?>): Any? {
            val types = Array(args.size) { args[it]!!.javaClass as Class<*> }
            return runS(cls, name, types, args)
        }

        @Throws(Exception::class)
        fun runA(inst: Any?, name: String, args: Array<Any?>): Any? {
            val types = Array(args.size) { args[it]!!.javaClass as Class<*> }
            return run(inst, name, types, args)
        }

        @Throws(Exception::class)
        fun batch(inst: Any?, vararg params: Array<Any?>) {
            for (param in params) {
                val method = param[0] as String
                if (param.size == 2) {
                    @Suppress("UNCHECKED_CAST")
                    val args = param[1] as Array<Any?>
                    val types = Array(args.size) { args[it]!!.javaClass as Class<*> }
                    run(inst, method, types, args)
                } else if (param.size == 3) {
                    @Suppress("UNCHECKED_CAST")
                    val args = param[2] as Array<Any?>
                    @Suppress("UNCHECKED_CAST")
                    val types = param[1] as Array<Class<*>>
                    run(inst, method, types, args)
                }
            }
        }

        @Throws(Exception::class)
        fun field(clsName: String, name: String): Any? {
            return field(cls(clsName), null, name)
        }

        @Throws(Exception::class)
        fun field(cls: Class<*>, name: String): Any? {
            return field(cls, null, name)
        }

        @Throws(Exception::class)
        fun field(inst: Any, name: String): Any? {
            return field(inst.javaClass, inst, name)
        }

        @Throws(Exception::class)
        fun field(cls: Class<*>, inst: Any?, name: String): Any? {
            val field = cls.getField(name)
            return field.get(inst)
        }
    }

    class JSON {
        companion object {
            private var JSONObject: Class<*>? = null
            private var JSONArray: Class<*>? = null

            @JvmStatic
            @Throws(Exception::class)
            fun init(loader: ClassLoader) {
                JSONObject = loader.loadClass("org.json.JSONObject")
                JSONArray = loader.loadClass("org.json.JSONArray")
            }

            @JvmStatic
            @Throws(Exception::class)
            fun map(): Any {
                return JSONObject!!.getConstructor(*ty()).newInstance(*ar())
            }

            @JvmStatic
            @Throws(Exception::class)
            fun array(): Any {
                return JSONArray!!.getConstructor(*ty()).newInstance(*ar())
            }

            @JvmStatic
            fun isMap(json: Any?, key: Any?): Boolean {
                return json != null && JSONObject!!.name == json.javaClass.name && key != null && key is String
            }

            @JvmStatic
            fun isArray(json: Any?, key: Any?): Boolean {
                return json != null && JSONArray!!.name == json.javaClass.name && key != null && key is Int
            }

            @JvmStatic
            @Throws(Exception::class)
            fun optMap(json: Any?, key: Any?): Any? {
                if (json == null) return null
                return when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("optJSONObject", *ty(String::class.java))
                        method.invoke(json, *ar(key))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("optJSONObject", *ty(Int::class.javaPrimitiveType!!))
                        method.invoke(json, *ar(key))
                    }
                    else -> null
                }
            }

            @JvmStatic
            @Throws(Exception::class)
            fun optArray(json: Any?, key: Any?): Any? {
                if (json == null) return null
                return when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("optJSONArray", *ty(String::class.java))
                        method.invoke(json, *ar(key))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("optJSONArray", *ty(Int::class.javaPrimitiveType!!))
                        method.invoke(json, *ar(key))
                    }
                    else -> null
                }
            }

            @JvmStatic
            @Throws(Exception::class)
            fun optStr(json: Any?, key: Any?, def: String?): String? {
                if (json == null) return def
                val ret: Any? = when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("optString", *ty(String::class.java, String::class.java))
                        method.invoke(json, *ar(key, def))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("optString", *ty(Int::class.javaPrimitiveType!!))
                        method.invoke(json, *ar(key, def))
                    }
                    else -> null
                }
                return ret?.toString()
            }

            @JvmStatic
            @Throws(Exception::class)
            fun optInt(json: Any?, key: Any?, def: Int?): Int? {
                if (json == null) return def
                val ret: Any? = when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("optInt", *ty(String::class.java))
                        method.invoke(json, *ar(key, def))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("optInt", *ty(Int::class.javaPrimitiveType!!))
                        method.invoke(json, *ar(key, def))
                    }
                    else -> null
                }
                if (ret == null) return def
                return try { ret.toString().toInt() } catch (ignore: Exception) { def }
            }

            @JvmStatic
            @Throws(Exception::class)
            fun opt(json: Any?, key: Any?, def: Any?): Any? {
                if (json == null) return def
                val ret: Any? = when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("opt", *ty(String::class.java))
                        method.invoke(json, *ar(key))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("opt", *ty(Int::class.javaPrimitiveType!!))
                        method.invoke(json, *ar(key))
                    }
                    else -> null
                }
                return ret ?: def
            }

            @JvmStatic
            @Throws(Exception::class)
            fun put(json: Any?, key: String, value: Any?) {
                when {
                    isMap(json, key) -> {
                        val method = JSONObject!!.getMethod("put", *ty(String::class.java, Any::class.java))
                        method.invoke(json, *ar(key, value))
                    }
                    isArray(json, key) -> {
                        val method = JSONArray!!.getMethod("put", *ty(Int::class.javaPrimitiveType!!, Any::class.java))
                        method.invoke(json, *ar(key, value))
                    }
                }
            }

            @JvmStatic
            @Throws(Exception::class)
            fun add(json: Any?, value: Any?) {
                if (isArray(json, 0)) {
                    val method = JSONArray!!.getMethod("put", *ty(Any::class.java))
                    method.invoke(json, *ar(value))
                }
            }

            @JvmStatic
            @Throws(Exception::class)
            fun size(json: Any?): Int {
                if (json == null) return 0
                if (isArray(json, 0)) {
                    val method = JSONArray!!.getMethod("length", *ty())
                    return method.invoke(json, *ar()) as Int
                }
                return 0
            }

            @JvmStatic
            @Suppress("UNCHECKED_CAST")
            @Throws(Exception::class)
            fun obj2JSON(obj: Any?): Any? {
                return when (obj) {
                    is Map<*, *> -> {
                        val map = obj as Map<String, Any>
                        val ret = map()
                        for (key in TreeSet(map.keys)) {
                            var item: Any? = map[key]
                            if (item is Map<*, *> || item is List<*>) {
                                item = obj2JSON(item)
                            }
                            put(ret, key, item)
                        }
                        ret
                    }
                    is List<*> -> {
                        val ret = array()
                        for (item in obj) {
                            var value = item
                            if (value is Map<*, *> || value is List<*>) {
                                value = obj2JSON(value)
                            }
                            add(ret, value)
                        }
                        ret
                    }
                    else -> null
                }
            }
        }
    }

    class JSONWriter(writer: Appendable) {
