package com.danawa.search.index

import java.io.BufferedReader
import java.io.File
import java.io.FileFilter
import java.io.FileInputStream
import java.io.InputStream
import java.io.InputStreamReader
import java.text.SimpleDateFormat
import java.util.regex.Pattern

import org.apache.logging.log4j.LogManager
import org.elasticsearch.client.internal.node.NodeClient

class DanawaBulkTextIndexer(
    private val indexName: String,
    private val path: String,
    private val enc: String,
    private val flush: Int,
    private val client: NodeClient
) : Thread(), FileFilter {

    @Volatile
    private var _running = false

    @Volatile
    private var _count = 0

    var files: MutableList<File> = mutableListOf()

    fun running(): Boolean = _running

    fun count(): Int = _count

    override fun run() {
        _running = true
        _count = 0
        files = mutableListOf()
        val paths = path.split(",")
        for (p in paths) {
            val trimmed = p.trim()
            val base = File(trimmed)
            if (!base.exists()) {
                logger.debug("BASE FILE NOT FOUND : {}", base)
            } else {
                if (base.isDirectory) {
                    base.listFiles(this)
                } else {
                    files.add(base)
                }
            }
        }

        if (files.size > 0) {
            var reader: BufferedReader? = null
            var istream: InputStream? = null
            val time = System.currentTimeMillis()
            var isSourceFile = false
            try {
                var builder = client.prepareBulk()
                var source: MutableMap<String, Any>

                for (file in files) {
                    if (!file.exists()) {
                        logger.debug("FILE NOT FOUND : {}", file)
                        continue
                    }
                    isSourceFile = false
                    istream = FileInputStream(file)
                    reader = BufferedReader(InputStreamReader(istream, enc))
                    logger.debug("PARSING FILE..{}", file)
                    var line = reader.readLine()
                    while (line != null) {
                        val mat = ptnHead.matcher(line)
                        var key: String? = null
                        var offset = 0
                        source = HashMap()
                        while (mat.find()) {
                            isSourceFile = true
                            if (key != null) {
                                fieldValue(source, key, line.substring(offset, mat.start()))
                            }
                            key = mat.group(1)
                            offset = mat.end()
                        }
                        if (isSourceFile) {
                            fieldValue(source, key!!, line.substring(offset))

                            builder.add(client.prepareIndex(indexName).setSource(source))
                            if (_count > 0 && _count % flush == 0) {
                                builder.execute().actionGet()
                                builder = client.prepareBulk()
                            }
                            if (_count > 0 && _count % 100000 == 0) {
                                logger.debug("{} ROWS FLUSHED! in {}ms", _count, System.currentTimeMillis() - time)
                            }
                        } else {
                            logger.debug("{} IS NOT SOURCEFILE", file)
                            break
                        }
                        _count++
                        line = reader.readLine()
                    }
                    try { reader.close() } catch (ignore: Exception) { }
                }
                builder.execute().actionGet()
                logger.debug("TOTAL {} ROWS in {}ms", _count, System.currentTimeMillis() - time)
            } catch (e: Exception) {
                logger.error("", e)
            } finally {
                try { reader?.close() } catch (ignore: Exception) { }
            }
        } else {
            logger.debug("THERE'S NO SOURCE FILE(S) FOUND")
        }
        _running = false
    }

    @Throws(Exception::class)
    private fun fieldValue(source: MutableMap<String, Any>, key: String, value: String) {
        if ("" == key) {
            // skip
        } else if ("REGISTERDATE" == key) {
            if (value.isNotEmpty()) {
                val sdf = SimpleDateFormat("yyyyMMdd")
                source[key] = sdf.parse(value)
            }
        } else {
            source[key] = value
        }
        logger.trace("ROW:{} / {}", key, value)
    }

    override fun accept(file: File): Boolean {
        if (!file.exists()) { return false }
        if (file.isDirectory) {
            file.listFiles(this)
        } else if (file.isFile) {
            files.add(file)
        }
        return false
    }

    companion object {
        @JvmStatic
        private val logger = LogManager.getLogger(DanawaBulkTextIndexer::class.java)

        @JvmStatic
        private val ptnHead = Pattern.compile("\\x5b[%]([a-zA-Z0-9_-]+)[%]\\x5d")
    }
}

package com.danawa.search.util

import java.text.SimpleDateFormat
import java.util.Date
import java.util.concurrent.TimeUnit

import com.danawa.search.analysis.highlight.TermHighlightingQuery
import com.danawa.search.analysis.product.ProductNameAnalyzerProvider

import org.apache.logging.log4j.LogManager
import org.apache.lucene.search.highlight.Highlighter
import org.apache.lucene.search.highlight.QueryScorer
import org.apache.lucene.search.highlight.SimpleHTMLEncoder
import org.apache.lucene.search.highlight.SimpleHTMLFormatter
import org.apache.lucene.util.BytesRef
import org.elasticsearch.action.bulk.BulkRequestBuilder
import org.elasticsearch.action.delete.DeleteRequest
import org.elasticsearch.action.search.ClearScrollRequest
import org.elasticsearch.action.search.SearchRequest
import org.elasticsearch.action.search.SearchResponse
import org.elasticsearch.action.search.SearchScrollRequest
import org.elasticsearch.action.update.UpdateRequest
import org.elasticsearch.client.internal.Client
import org.elasticsearch.client.internal.node.NodeClient
import org.elasticsearch.core.TimeValue
import org.elasticsearch.xcontent.XContentType
import org.elasticsearch.index.query.QueryBuilder
import org.elasticsearch.index.query.QueryBuilders
import org.elasticsearch.index.query.MatchQueryBuilder
import org.elasticsearch.search.SearchHit
import org.elasticsearch.search.builder.SearchSourceBuilder
import org.elasticsearch.search.fetch.subphase.highlight.HighlightBuilder
import org.elasticsearch.search.sort.SortBuilder

class SearchUtil {

    companion object {
        @JvmStatic
        private val DEFAULT_SCROLL_KEEP_ALIVE: TimeValue = TimeValue.timeValueMinutes(1L)

        @JvmStatic
        private val DEFAULT_SEARCH_TIME_OUT: TimeValue = TimeValue(60, TimeUnit.SECONDS)

        private const val DEFAULT_SCROLL_SIZE = 10000

        @JvmStatic
        private val logger = LogManager.getLogger(SearchUtil::class.java)

        @JvmStatic
        fun searchData(client: NodeClient, index: String): Map<String, Any> {
            val result = mutableMapOf<String, Any>()
            try {
                val searchRequest = SearchRequest()
                searchRequest.indices(index).source(
                    SearchSourceBuilder.searchSource().query(QueryBuilders.matchAllQuery()).size(10000)
                )
                val response = client.search(searchRequest).actionGet()

                for (hit in response.hits.hits) {
                    val id = hit.sourceAsMap["id"] as String
                    val updatedTime = (hit.sourceAsMap["updatedTime"] as? String) ?: ""
                    val appliedTime = (hit.sourceAsMap["appliedTime"] as? String) ?: ""
                    val count = (hit.sourceAsMap["count"] as? Int) ?: 0
                    result[id] = count
                    result["${id}_appliedTime"] = appliedTime
                    result["${id}_updatedTime"] = updatedTime
                }
            } catch (e: Exception) {
                logger.error("{}", e)
            }
            return result
        }

        @JvmStatic
        fun upsertData(client: NodeClient, index: String, data: Map<String, Any>) {
            logger.info("{}", data)
            val cnt = data["cnt"] as Int
            val sdf = SimpleDateFormat("yyyy-MM-dd HH:mm:ss")

            try {
                val record = mutableMapOf<String, Any>()
                record["id"] = data["id"]!!
                record["appliedTime"] = sdf.format(Date())
                record["count"] = cnt
                val updateRequest = UpdateRequest(index, data["id"] as String)
                    .docAsUpsert(true).upsert(record, XContentType.JSON).doc(record, XContentType.JSON)
                val response = client.update(updateRequest).actionGet()
            } catch (e: Exception) {
                logger.error("{}", e)
            }
        }

        @JvmStatic
        fun deleteAllData(client: NodeClient, index: String) {
            var builder: BulkRequestBuilder = client.prepareBulk()
            var hits: Array<SearchHit>?
            var clearScroll: ClearScrollRequest?
            var scrollId: String?

            try {
                val query = QueryBuilders.matchAllQuery()
                val source = SearchSourceBuilder()
                source.query(query)
                val search = SearchRequest(*index.split("[,]".toRegex()).toTypedArray())
                clearScroll = ClearScrollRequest()
                source.from(0)
                source.size(DEFAULT_SCROLL_SIZE)
                source.timeout(DEFAULT_SEARCH_TIME_OUT)
                search.source(source)
                search.scroll(DEFAULT_SCROLL_KEEP_ALIVE)
                var response = client.search(search).get()
                hits = response.hits.hits
                scrollId = response.scrollId
                clearScroll.addScrollId(scrollId)

                var totInx = 0
                while (hits != null && hits.isNotEmpty()) {
                    for (inx in hits.indices) {
                        val request = DeleteRequest(index, hits[inx].id)
                        builder.add(request)
                        if (totInx > 0 && totInx % 5000 == 0) {
                            builder.execute().actionGet()
                            builder = client.prepareBulk()
                        }
                        totInx++
                    }
                    val scrollRequest = SearchScrollRequest(scrollId)
                    scrollRequest.scroll(DEFAULT_SCROLL_KEEP_ALIVE)
                    response = client.searchScroll(scrollRequest).get()
                    hits = response.hits.hits
                    scrollId = response.scrollId
                    clearScroll.addScrollId(scrollId)
                }
                if (totInx > 0) {
                    builder.execute().actionGet()
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        @JvmStatic
        fun count(client: Client, index: String, query: QueryBuilder): Long {
            var ret = 0L
            try {
                val countRequest = SearchRequest(*index.split("[,]".toRegex()).toTypedArray())
                val countSource = SearchSourceBuilder().query(query).size(0).trackTotalHits(true)
                countRequest.source(countSource)
                val countResponse = client.search(countRequest).get()
                ret = countResponse.hits.totalHits!!.value()
            } catch (e: Exception) {
                logger.error("", e)
            }
            return ret
        }

        @JvmStatic
        fun count(client: RemoteNodeClient, index: String, query: QueryBuilder): Long {
            return client.count(index, query as MatchQueryBuilder)
        }

        @JvmStatic
        fun search(
            client: Client, index: String, query: QueryBuilder,
            sortSet: List<SortBuilder<*>>?, highlight: HighlightBuilder?,
            from: Int, size: Int, doScroll: Boolean, dataModifier: DataModifier?
        ): Iterator<Map<String, Any>>? {
            return if (doScroll) {
                ScrollSearchResultIterator().doSearch(client, index, query, sortSet, highlight, dataModifier, from, size)
            } else {
                SearchResultIterator().doSearch(client, index, query, sortSet, highlight, dataModifier, from, size)
            }
        }

        @JvmStatic
        fun highlightString(str: String?, wordSet: List<String>, tags: List<String>): String? {
            var ret: String? = null
            if (str != null) {
                val trimmed = str.trim()
                if (trimmed.isNotEmpty()) {
                    val tstream = ProductNameAnalyzerProvider.getAnalyzer(trimmed, false, false, true, false, true)
                    val terms = mutableListOf<BytesRef>()
                    for (word in wordSet) {
                        terms.add(BytesRef(word.uppercase()))
                    }
                    var preTag: String? = null
                    var postTag: String? = null
                    if (tags.size > 1) {
                        preTag = tags[0]
                        postTag = tags[1]
                    }
                    if (preTag != null && postTag != null) {
                        val query = TermHighlightingQuery("", terms)
                        val formatter = if (preTag.isNotEmpty() && postTag.isNotEmpty()) {
                            SimpleHTMLFormatter(preTag, postTag)
                        } else {
                            SimpleHTMLFormatter()
                        }
                        val encoder = SimpleHTMLEncoder()
                        val scorer = QueryScorer(query)
                        val highlighter = Highlighter(formatter, encoder, scorer)
                        try {
                            ret = highlighter.getBestFragment(tstream, trimmed)
                        } catch (e: Exception) {
                            logger.debug("highlight error {} / {} / {}", trimmed, wordSet, e.message)
                            logger.error("", e)
                        }
                        if (ret == null) {
                            ret = trimmed
                        }
                    }
                }
            }
            return ret
        }
    }

    abstract class DataModifier {
        abstract fun modify(map: MutableMap<String, Any>)
    }

    internal abstract class AbstractSearchResultIterator : Iterator<Map<String, Any>> {
        companion object {
            const val FIELD_ROWNUM = "_ROWNUM"
            const val FIELD_SORT = "_SORT"
            const val FIELD_HIGHLIGHT = "_HIGHLIGHT"

            fun processHit(hit: SearchHit, rowNum: Int, dataModifier: DataModifier?): Map<String, Any> {
                val rowData = hit.sourceAsMap
                rowData[FIELD_ROWNUM] = rowNum
                rowData[FIELD_SORT] = hit.sortValues
                dataModifier?.modify(rowData)
                return rowData
            }
        }

        abstract fun doSearch(
            client: Client, index: String, query: QueryBuilder,
            sortSet: List<SortBuilder<*>>?, highlight: HighlightBuilder?,
            dataModifier: DataModifier?, from: Int, size: Int
        ): Iterator<Map<String, Any>>?
    }

    internal class SearchResultIterator : AbstractSearchResultIterator() {
        private var hits: Array<SearchHit>? = null
        private var rowNum = 0
        private var hitsInx = 0
        private var rowData: Map<String, Any>? = null
        private var timeOut: TimeValue? = null
        private var dataModifier: DataModifier? = null

        override fun doSearch(
            client: Client, index: String, query: QueryBuilder,
            sortSet: List<SortBuilder<*>>?, highlight: HighlightBuilder?,
            dataModifier: DataModifier?, from: Int, size: Int
        ): Iterator<Map<String, Any>>? {
            try {
                val source = SearchSourceBuilder()
                sortSet?.forEach { sort -> source.sort(sort) }
                this.dataModifier = dataModifier
                source.query(query)
                val search = SearchRequest(*index.split("[,]".toRegex()).toTypedArray())
                source.from(from)
                source.size(size)
                source.timeout(timeOut)
                search.source(source)
                val response = client.search(search).get()
                hits = response.hits.hits
                rowNum = from
                rowData = null
                return this
            } catch (e: Exception) {
                logger.debug("SEARCH ERROR : {} ( It may be over 10,000 records ) ", e.message)
            }
            return null
        }

        override fun hasNext(): Boolean {
            if (rowData != null) { return true }
            try {
                val h = hits
                if (h != null && h.isNotEmpty()) {
                    if (hitsInx < h.size) {
                        rowData = processHit(h[hitsInx], rowNum, dataModifier)
                        hitsInx++
                        rowNum++
                    }
                    return rowData != null
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return false
        }

        override fun next(): Map<String, Any> {
            val ret = rowData!!
            rowData = null
            return ret
        }

        fun close() { }
    }

    internal class ScrollSearchResultIterator : AbstractSearchResultIterator {

        private var client: Client? = null
        private var hits: Array<SearchHit>? = null
        private var clearScroll: ClearScrollRequest? = null
        private var scrollId: String? = null
        private var rowNum = 0
        private var hitsInx = 0
        private var rowData: Map<String, Any>? = null
        private var scrollKeepAlive: TimeValue
        private var timeOut: TimeValue
        private var dataModifier: DataModifier? = null
        private var scrollSize: Int
        private var size = 0

        constructor() : this(DEFAULT_SEARCH_TIME_OUT, DEFAULT_SCROLL_KEEP_ALIVE, DEFAULT_SCROLL_SIZE)

        constructor(timeOut: TimeValue, scrollKeepAlive: TimeValue, scrollSize: Int) {
            this.scrollKeepAlive = scrollKeepAlive
            this.timeOut = timeOut
            this.scrollSize = scrollSize
        }

        override fun doSearch(
            client: Client, index: String, query: QueryBuilder,
            sortSet: List<SortBuilder<*>>?, highlight: HighlightBuilder?,
            dataModifier: DataModifier?, from: Int, size: Int
        ): Iterator<Map<String, Any>>? {
            try {
                this.client = client
                val source = SearchSourceBuilder()
                sortSet?.forEach { sort -> source.sort(sort) }
                this.dataModifier = dataModifier
                source.query(query)
                val search = SearchRequest(*index.split("[,]".toRegex()).toTypedArray())
                clearScroll = ClearScrollRequest()
                source.from(0)
                source.size(scrollSize)
                source.timeout(timeOut)
                search.source(source)
                search.scroll(scrollKeepAlive)
                var response = client.search(search).get()
                hits = response.hits.hits
                scrollId = response.scrollId
                clearScroll!!.addScrollId(scrollId)
                rowNum = 0
                while (hits != null && hits!!.isNotEmpty() && rowNum < from) {
                    if (rowNum + hits!!.size <= from) {
                        rowNum += hits!!.size
                    } else {
                        hitsInx = from - rowNum
                        rowNum = from
                        break
                    }
                    val scrollRequest = SearchScrollRequest(scrollId)
                    scrollRequest.scroll(scrollKeepAlive)
                    response = client.searchScroll(scrollRequest).get()
                    hits = response.hits.hits
                    scrollId = response.scrollId
                    clearScroll!!.addScrollId(scrollId)
                }
                this.size = size
                rowData = null
                return this
            } catch (e: Exception) {
                logger.error("", e)
            }
            return null
        }

        override fun hasNext(): Boolean {
            if (rowData != null) { return true }
            try {
                while (hits != null && hits!!.isNotEmpty() && (size == -1 || size > 0)) {
                    while (hitsInx < hits!!.size && (size == -1 || size > 0)) {
                        rowData = processHit(hits!![hitsInx], rowNum, dataModifier)
                        hitsInx++
                        rowNum++
                        if (size != -1) {
                            size--
                        }
                        break
                    }

                    if (rowData != null) {
                        return true
                    }

                    val scrollRequest = SearchScrollRequest(scrollId)
                    scrollRequest.scroll(scrollKeepAlive)
                    val response = client!!.searchScroll(scrollRequest).get()
                    hits = response.hits.hits
                    scrollId = response.scrollId
                    clearScroll!!.addScrollId(scrollId)
                    hitsInx = 0
                }
                if (size == 0 || (hits == null && rowData == null)) {
                    close()
                    return false
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return false
        }

        override fun next(): Map<String, Any> {
            val ret = rowData!!
            rowData = null
            return ret
        }

        fun close() {
            try {
                client?.clearScroll(clearScroll).get()
            } catch (ignore: Exception) { }
        }
    }
}

