    private fun distribute(client: NodeClient, action: String, body: JSONObject, selfDist: Boolean) {
        val localNodeId = client.localNodeId
        val infoRequest = NodesInfoRequest()
        infoRequest.clear()
            .addMetrics(NodesInfoMetrics.Metric.JVM.metricName())
            .addMetrics(NodesInfoMetrics.Metric.OS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PROCESS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.HTTP.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PLUGINS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.INDICES.metricName())

        try {
            val response = client.admin().cluster().nodesInfo(infoRequest).get()
            val nodes = response.nodes
            for (node in nodes) {
                if (!selfDist && localNodeId == node.node.id) {
                    continue
                }
                var hasPlugin = false
                val address = node.getInfo(HttpInfo::class.java).address().publishAddress()
                val plugins = node.getInfo(PluginsAndModules::class.java).pluginInfos
                for (info in plugins) {
                    hasPlugin = info.descriptor().classname == AnalysisProductNamePlugin::class.java.name
                    if (hasPlugin) break
                }
                if (hasPlugin) {
                    logger.debug("NODE: {}:{}", address.address, address.port)
                    doRestRequest(address.address, address.port, action, body)
                }
            }
        } catch (e: Exception) {
            logger.error("", e)
        }
    }

    private fun doRestRequest(address: String, port: Int, action: String, body: JSONObject): String {
        val sb = StringBuilder()
        var con: HttpURLConnection? = null
        var ostream: OutputStream? = null
        var reader: BufferedReader? = null
        try {
            val url = "http://$address:$port$BASE_URI/$action"
            logger.debug("SEND REQUEST {}", url)
            con = URL(url).openConnection() as HttpURLConnection
            con.requestMethod = "POST"
            con.setRequestProperty("Content-Type", "application/json")
            con.doOutput = true
            ostream = con.outputStream
            ostream.write(body.toString().toByteArray())
            ostream.flush()
            val responseCode = con.responseCode
            if (responseCode == HttpURLConnection.HTTP_CREATED) {
                logger.trace("RESPONSE:{}", responseCode)
                reader = BufferedReader(InputStreamReader(con.inputStream))
                var rl: String?
                while (reader.readLine().also { rl = it } != null) {
                    sb.append(rl).append("\r\n")
                }
                logger.trace("RESPONSE:{}", sb)
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { ostream?.close() } catch (ignore: Exception) { }
            try { reader?.close() } catch (ignore: Exception) { }
        }
        return sb.toString()
    }

