    private fun analyzeMultiParamsAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        logger.debug("multi-params Action")
        val index = ES_DICTIONARY_INDEX
        val useForQuery = false
        val useSynonym = true
        val useStopword = false
        val useFullString = true

        val analyzeMap: MutableMap<String, String> = HashMap()
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            for (key in jparam.keySet()) {
                analyzeMap[key] = jparam.optString(key, "")
            }
        } else {
            try {
                for (key in request.params().keys) {
                    if (key == "action" || key == "pretty") continue
                    analyzeMap[key] = URLDecoder.decode(request.param(key, ""), "UTF-8")
                }
            } catch (e: UnsupportedEncodingException) {
                logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.message)
                writer.key("success").value(false)
                logger.debug("error >>> {}", e)
            }
        }

        var stream: TokenStream? = null
        writer.key("result").`object`()
        try {
            for (key in analyzeMap.keys) {
                val value = analyzeMap[key]
                logger.debug("key : {} :::::: value : {}", key, value)
                stream = ProductNameAnalyzerProvider.getAnalyzer(value!!, useForQuery, useSynonym, useStopword, useFullString, false)
                val list = analyzeMultiParamsText(null, value, stream, index, useForQuery)
                if (list.size != 0) {
                    writer.key(key).array()
                    for (item in list) {
                        writer.value(item)
                    }
                    writer.endArray()
                }
                stream.close()
            }
        } catch (ignore: Exception) {
            writer.endObject()
            writer.key("success").value(false)
            logger.debug("exception >>> {}", ignore)
            logger.error("Exception Catched !!! >>>> \n" + ignore.message)
        } finally {
            writer.endObject()
            writer.key("success").value(true)
        }
    }

