    private fun bulkIndex(request: RestRequest, client: NodeClient): Int {
        var ret = 0
        var jparam = JSONObject()
        var index = request.param("index", "")
        var path = request.param("path", "")
        var enc = request.param("enc", "euc-kr")
        var flush = request.paramAsInt("flush", 50000)
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", "")
            path = jparam.optString("path", "")
            enc = jparam.optString("enc", "euc-kr")
            flush = jparam.optInt("flush", 50000)
        }

        synchronized(this) {
            if (indexingThread == null || !indexingThread!!.running()) {
                indexingThread = DanawaBulkTextIndexer(index, path, enc, flush, client)
                indexingThread!!.start()
            } else {
                ret = indexingThread!!.count()
            }
        }
        return ret
    }

