    private fun search(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", "")
        var fields = request.param("fields", "").split("[,]".toRegex()).toTypedArray()
        val boostMap: MutableMap<String, Float> = HashMap()
        var text = request.param("text", "")
        var queryString = request.param("query", "")
        var totalIndex = request.param("totalIndex", ES_INDEX_TOTALINDEX)
        var from = request.paramAsInt("from", 0)
        var size = request.paramAsInt("size", 20)
        var showTotal = request.paramAsBoolean("showTotal", false)
        var showExplain = request.paramAsBoolean("showExplain", false)
        var showDetail = request.paramAsBoolean("showDetail", false)
        var useScroll = request.paramAsBoolean("useScroll", false)
        var sortStr = request.param("sort")
        var highlightStr = request.param("highlight")
        var analyzer = request.param("analyzer", "whitespace")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", "")
            fields = jparam.optString("fields", "").split("[,]".toRegex()).toTypedArray()
            text = jparam.optString("text", "")
            queryString = jparam.optString("query", "")
            totalIndex = jparam.optString("totalIndex", ES_INDEX_TOTALINDEX)
            from = jparam.optInt("from", 0)
            size = jparam.optInt("size", 20)
            showTotal = jparam.optBoolean("showTotal", false)
            showExplain = jparam.optBoolean("showExplain", false)
            showDetail = jparam.optBoolean("showDetail", false)
            useScroll = jparam.optBoolean("useScroll", false)
            sortStr = jparam.optString("sort")
            highlightStr = jparam.optString("highlight")
            analyzer = jparam.optString("analyzer", "whitespace")
        }

        for (inx in fields.indices) {
            val item = fields[inx].split("[\\^]".toRegex()).toTypedArray()
            val field = item[0].trim()
            if (item.size > 1) {
                var boost = 1.0f
                try { boost = item[1].trim().toFloat() } catch (ignore: Exception) { }
                boostMap[field] = boost
            }
            fields[inx] = field
        }

        var stream: TokenStream? = null
        try {
            logger.trace("ANALYZE TEXT : {}", text)
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, true, true, true, false)
            var explain: JSONObject? = null
            if (showExplain) { explain = JSONObject() }

            var sortSet: List<*>? = null
            if (sortStr != null && "" != sortStr) {
                logger.trace("SORT:{}", sortStr)
                sortSet = DanawaSearchQueryBuilder.parseSortSet(sortStr)
            }

            var highlight: HighlightBuilder? = null
            val views: MutableList<String> = ArrayList()
            val highlightTags: MutableList<String> = ArrayList()
            if (highlightStr != null && "" != highlightStr) {
                logger.trace("HIGHLIGHT:{}", highlightStr)
                highlight = DanawaSearchQueryBuilder.parseHighlight(highlightStr)
                val preTags = highlight.preTags()
                val postTags = highlight.postTags()
                if (preTags.isNotEmpty() && postTags.isNotEmpty()) {
                    highlightTags.add(preTags[0])
                    highlightTags.add(postTags[0])
                }
                for (field in highlight.fields()) {
                    val name = field.name()
                    logger.trace("FIELD:{}", name)
                    if ("_all" != name) {
                        views.add(name)
                    }
                }
            }

            val highlightTerms: MutableList<String> = ArrayList()
            var query: QueryBuilder = DanawaSearchQueryBuilder.buildAnalyzedQuery(stream, fields, totalIndex, boostMap, views, highlightTerms, explain, analyzer)
            if (queryString != null && "" != queryString) {
                try {
                    val baseQuery = DanawaSearchQueryBuilder.parseQuery(queryString)
                    logger.trace("Q:{}", baseQuery)
                    if (baseQuery is FunctionScoreQueryBuilder) {
                        val innerQuery = baseQuery.query()
                        if (innerQuery is BoolQueryBuilder) {
                            innerQuery.must().clear()
                            innerQuery.must(query)
                            logger.trace("Q:{}", innerQuery)
                        }
                        query = baseQuery
                    }
                } catch (e: Exception) {
                    logger.error("", e)
                }
            }
            logger.trace("Q:{}", query)
            var total: Long = -1
            if (showTotal) {
                total = SearchUtil.count(client as Client, index, query)
            }

            val doScroll = if (!useScroll) false else from + size > 10000
            builder.`object`()
            if (showExplain) { builder.key("explain").value(explain) }
            if (showDetail) { builder.key("detail").value(JSONObject(query.toString())) }
            if (total != -1L) { builder.key("total").value(total) }
            builder.key("result").array()

            val dataModifier = object : DataModifier() {
                override fun modify(map: MutableMap<String, Any>) {
                    for (field in views) {
                        if (map.containsKey(field)) {
                            val obj = map[field]
                            if (obj is String) {
                                map[field] = SearchUtil.highlightString(obj, highlightTerms, highlightTags)
                            }
                        }
                    }
                }
            }
            @Suppress("UNCHECKED_CAST")
            val iter = SearchUtil.search(client as Client, index, query, sortSet as List<org.elasticsearch.search.sort.SortBuilder<*>>?, highlight, from, size, doScroll, dataModifier)
            while (iter != null && iter.hasNext()) {
                val map = iter.next()
                builder.`object`()
                for (key in map.keys) {
                    builder.key(key).value(map[key])
                }
                builder.endObject()
            }
            builder.endArray()
            builder.endObject()
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }
    }

    private fun buildQuery(request: RestRequest, client: NodeClient, builder: JSONWriter) {
