        @JvmStatic
        fun isOneWaySynonym(client: NodeClient?, index: String?, word: String): Boolean {
            var ret = false
            if (client != null && index != null && "" != index) {
                val query = QueryBuilders.boolQuery()
                    .must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, ProductNameDictionary.DICT_SYNONYM.uppercase()))
                    .must(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                logger.trace("Q:{}", query)
                val count = SearchUtil.count(client as Client, index, query)
                if (count > 0) { ret = true }
                logger.trace("SYNONYM:{}-{} = {}", index, word, count)
            } else {
                val dictionary = getDictionary()!!
                val synonyms = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
                ret = ProductNameDictionary.isOneWaySynonym(CharVector.valueOf(word), synonyms.map())
            }
            return ret
        }

