        private fun getAnalyzeSynonym(combineTerm: String, useforQuery: Boolean): List<CharSequence> {
            val result: MutableList<CharSequence> = ArrayList()
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(combineTerm, true, true, true, true, false)
                val synAtr = analyzerStream.addAttribute(SynonymAttribute::class.java)
                val typeAttr = analyzerStream.addAttribute(TypeAttribute::class.java)
                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    val synonyms = synAtr.synonyms
                    if (synonyms != null && synonyms.isNotEmpty()) {
                        for (synonym in synonyms) {
                            val type = typeAttr.type()
                            if (type == ProductNameTokenizer.FULL_STRING && useforQuery) {
                                result.add(synonym)
                            } else if (!useforQuery) {
                                result.add(synonym)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return result
        }

