                    offsetPrev = intArrayOf(offset[0], offset[1])
                    val term = termAttr.toString()
                    var termWords: MutableList<Any> = ArrayList()
                    val extraTermWords: MutableList<Any> = ArrayList()
                    val type = typeAttr.type()
                    offset = intArrayOf(offAttr.startOffset(), offAttr.endOffset())
                    logger.trace("TERM:{} / {}", term, type)

                    if (type == ProductNameTokenizer.FULL_STRING) {
                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
