                                val s = synonym.toString()
                                val synonymList = s.split(" ".toRegex()).toTypedArray()
                                if (synonymList.size > 1) { termWords.add(synonymList) } else { termWords.add(s) }
                            }
                            combineTermSynonym[term] = termWords
                        }
                    } else {
                        tempTermList.add(term)
                        if (offset[0] < offsetPrev[1]) {
                            termWords.add(term)
                            offset = intArrayOf(offsetPrev[0], offsetPrev[1])
                        } else {
                            termWords.add(term)
                        }

                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            logger.trace("SYNONYM {} / {} ", term, synonyms)
                            for (synonym in synonyms) {
                                val s = synonym.toString()
                                val synonymList = s.split(" ".toRegex()).toTypedArray()
                                if (synonymList.size > 1) { termWords.add(synonymList) } else { termWords.add(s) }
