                                val extSynonyms = synAttr.synonyms
                                if (extSynonyms != null && extSynonyms.isNotEmpty()) {
                                    val extensionSynonym: MutableMap<String, Any> = HashMap()
                                    val extSynonymList: MutableList<String> = ArrayList()
                                    extraTermWords.remove(s)
                                    logger.trace("EXT-SYN {} / {} / {}", term, s, extSynonyms)
                                    for (synonym in extSynonyms) {
