        private fun putSynonymData(combineTermSynonym: MutableMap<String, Any>, synonymDict: SynonymDictionary, combineTerm: String) {
            val dictData = synonymDict.get(CharVector(combineTerm))
            if (dictData != null) {
                combineTermSynonym[combineTerm] = removeDuplicates(findSynonymTerm(combineTerm, dictData))
            }
        }

        private fun findSynonymTerm(combineTerm: String, dictData: Array<CharSequence>): ArrayList<Any> {
            val result = ArrayList<Any>()
            result.add(divideTerm(combineTerm))
            for (v in dictData) {
                val value = v.toString()
                try {
                    val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(value, true, false, false, false, false)
                    val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                    analyzerStream.reset()
                    val subResult = ArrayList<Any>()
                    while (analyzerStream.incrementToken()) {
                        subResult.add(termAtr.toString())
                    }
                    result.add(subResult)
                } catch (e: Exception) {
                    logger.error("", e)
                }
            }
            return result
        }

        private fun divideTerm(keyword: String): ArrayList<Any> {
            val result = ArrayList<Any>()
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(keyword, true, false, false, false, false)
                val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    result.add(termAtr.toString())
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return result
        }

        private fun <T> removeDuplicates(list: ArrayList<T>): ArrayList<T> {
            val newList = ArrayList<T>()
            for (element in list) {
                if (!newList.contains(element)) { newList.add(element) }
            }
            return newList
        }

