        fun getSynonymList(text: String, stream: TokenStream, writer: JSONWriter) {
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val result: MutableMap<String, MutableList<MutableList<String>>> = HashMap()
            for (key in ANALYSIS_RESULT_LABELS.keys) {
                result[key] = ArrayList()
            }
            var term: String
            var type: String?
            var setName: String?
            try {
                stream.reset()
                while (stream.incrementToken()) {
                    term = termAttr.toString()
                    type = typeAttr.type()
                    logger.trace("TERM:{} / {}", term, type)
                    if (ProductNameTokenizer.FULL_STRING == type) {
                        setName = ANALYZE_SET_FULL_STRING
                        setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL)
                    } else if (ProductNameTokenizer.MODEL_NAME == type) {
                        setName = ANALYZE_SET_MODEL_NAME
                        setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_FINAL)
                    } else {
                        setName = ANALYZE_SET_NORMAL
                        setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                    }

                    if (ANALYZE_SET_FULL_STRING != setName) {
                        val synonyms = synAttr.synonyms
                        if (synonyms != null && synonyms.isNotEmpty()) {
                            if (term == text) {
                                for (synonym in synonyms) {
                                    writer.value(synonym.toString())
                                }
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        private fun getDictionary(): ProductNameDictionary? {
            return contextStore.getAs(ProductNameDictionary.PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
        }
